'use strict';
// Please note: Do not remove this line or asset references may break.
export let __workshopId = '2652493753';

const NUM_BARS = 64;
const FULL_CIRCLE_DEGREES = 360;


export var scriptProperties = createScriptProperties()
    .addSlider({
        name: 'barWidth',
        label: 'Width粗细',
        value: 5,
        min: 0,
        max: 10,
        integer: false
    })
    .addSlider({
        name: 'scaleY',
        label: 'bounce height弹跳高度',
        value: 50,
        min: 0,
        max: 100,
        integer: false
    })
    .addSlider({
        name: 'originX',
        label: 'Distance距离',
        value: 30,
        min: -60,
        max: 60,
        integer: false
    })
    .addSlider({
        name: 'originY',
        label: 'Audio Bar height音频条高度',
        value: 0,
        min: -60,
        max: 60,
        integer: false
    })
    .addSlider({
        name: 'anglesY',
        label: 'Audio Bar Angles音频条角度',
        value: 0,
        min: -90,
        max: 90,
        integer: false
    })
    .addCombo({
        name: 'barAlignmentdir',
        label: 'Direction形态',
        options: [{
            label: 'Centre居中',
            value: 'centre'
        }, {
            label: 'Bottom底边对齐',
            value: 'bottom'
        }, {
            label: 'Top顶部对齐',
            value: 'top'
        }]
    })
    .finish();

var bars = [];
var baseOrigin;
var baseAngle;
let audioData = engine.registerAudioBuffers(NUM_BARS);

export function update() {
    const barAlignment = scriptProperties.barAlignmentdir;

    for (var i = 0; i < NUM_BARS; ++i) {
        try {
            let amt = audioData.average[i];
            let bar = bars[i];

            let origin = baseOrigin.copy();
            let scale = new Vec3(scriptProperties.barWidth, amt * scriptProperties.scaleY, 0);

            origin.x += scriptProperties.originX * i;
            origin.y += scriptProperties.originY * i;

            if (bar.alignment !== barAlignment) {
                bar.alignment = barAlignment;
            }

            bar.scale = scale;
            bar.origin = origin;
        } catch (error) {
            console.error('发生错误：', error);
        }
    }
}

export function init() {
    bars.push(thisLayer);
    let thisIndex = thisScene.getLayerIndex(thisLayer);
    for (var i = 1; i < NUM_BARS; ++i) {
        let bar = thisScene.createLayer('models/bar.json');
        bar.alignment = scriptProperties.barAlignmentdir;
        thisScene.sortLayer(bar, thisIndex);
        bar.parallaxDepth = new Vec2(0, 0);
        bars.push(bar);
    }

    for (var i = 0; i < NUM_BARS; ++i) {
        let angle = FULL_CIRCLE_DEGREES * (i / NUM_BARS);
        let bar = bars[i];
        bar.angles = new Vec3(0, 0, scriptProperties.anglesY);
    }

    baseOrigin = thisLayer.origin;
}
